#!/bin/bash
# Security checks for the Supabase schema: RLS, column grants, the security
# definer functions, triggers (rewards, limits, pushes), run as guest, free
# user, Pro user and admin against a database built from every migration.
# Run through run.sh, not directly. Checks build on each other in order.
source "$(dirname "$0")/lib.sh"
echo "### Guest (anon)"
t "guest reads approved meals" anon =20 "select count(*) from meals"
t "guest cannot insert a meal" anon deny "insert into meals(name,status) values ('x','approved')"
t "guest cannot edit ingredient prices (0 rows)" anon =0 "with u as (update ingredients set estimated_price=1 returning 1) select count(*) from u"
t "guest cannot read users" anon =0 "select count(*) from users"
t "guest cannot call count_daily_use" anon deny "select * from count_daily_use('search','x')"
t "guest cannot read food posts feed" anon deny "select count(*) from get_food_posts() where image_url like '%real.jpg'"
t "guest cannot save a meal" anon deny "insert into saved_meals(user_id,meal_key,meal_data) values ('$A','k','{}')"
t "guest cannot write daily_prices" anon deny "insert into daily_prices(da_commodity_id,price_date,price) values (gen_random_uuid(), now(), 1)"
echo "### Account row lockdown"
t "user cannot grant self Pro (pro_until)" A deny "update users set pro_until=now()+interval '1 year' where id='$A'"
t "user cannot grant self reward days" A deny "update users set pro_reward_until=now()+interval '1 year' where id='$A'"
t "user cannot set tier=pro" A deny "update users set tier='pro' where id='$A'"
t "user cannot change email column" A deny "update users set email='x@y' where id='$A'"
t "user can edit display name" A ok "update users set display_name='Alice A' where id='$A'"
t "user cannot edit someone else's name (0 rows)" A =0 "with u as (update users set display_name='pwned' where id='$B' returning 1) select count(*) from u"
t "display_name length is capped (300 chars)" A deny "update users set display_name=repeat('x',300) where id='$A'"
t "display_name accepts 255 chars of anything" A ok "update users set display_name=repeat('W',255) where id='$A'"
t "avatar must be own upload (external URL)" A deny "update users set avatar_url='https://evil.example/x.png' where id='$A'"
t "avatar own folder ok" A ok "update users set avatar_url='$BASE/post-images/$A/avatar-1.jpg' where id='$A'"
t "user can call is_pro (should be denied)" A deny "select is_pro('$PRO')"
echo "### Recipes (meals)"
t "submit own pending recipe" A ok "insert into meals(id,name,status,poster_id,save_count) values ('33333333-0000-0000-0000-000000000001','Alice adobo','pending','$A',9999)"
t "save_count forced to 0 on submit" svc =0 "select save_count from meals where id='33333333-0000-0000-0000-000000000001'"
t "cannot submit already-approved recipe" A deny "insert into meals(name,status,poster_id) values ('x','approved','$A')"
t "cannot submit as someone else" A deny "insert into meals(name,status,poster_id) values ('x','pending','$B')"
t "cannot self-approve via update" A deny "update meals set status='approved' where id='33333333-0000-0000-0000-000000000001'"
t "external cover image refused" A deny "update meals set image_url='https://evil.example/x.jpg' where id='33333333-0000-0000-0000-000000000001'"
t "S1: poster cannot set procedure_audio (ignored)" A ok "update meals set procedure_audio=array['https://evil.example/a.mp3','https://evil.example/b.mp3'] where id='33333333-0000-0000-0000-000000000001'"
t "poster sets arbitrary price/calories (pre-approval)" A ok "update meals set price=1, calories=1 where id='33333333-0000-0000-0000-000000000001'"
t "other user cannot read A's pending recipe" B =0 "select count(*) from meals where id='33333333-0000-0000-0000-000000000001'"
t "other user cannot delete A's recipe (0 rows)" B =0 "with d as (delete from meals where id='33333333-0000-0000-0000-000000000001' returning 1) select count(*) from d"
t "user cannot edit catalog meal (0 rows)" A =0 "with u as (update meals set price=1 where status='approved' returning 1) select count(*) from u"
t "user cannot add lines to catalog meal" A deny "insert into meal_ingredients(meal_id,ingredient_id,display_text) values ('11111111-0000-0000-0000-000000000001','22222222-0000-0000-0000-000000000001','x')"
t "user adds line to own pending recipe" A ok "insert into meal_ingredients(meal_id,ingredient_id,display_text) values ('33333333-0000-0000-0000-000000000001','22222222-0000-0000-0000-000000000001','pork 500g')"
t "user cannot create ingredients" A deny "insert into ingredients(canonical_name,price_source) values ('fake','manual')"
echo "### Storage"
t "upload photo into own pending recipe folder" A ok "insert into storage.objects(bucket_id,name) values ('meal-images','33333333-0000-0000-0000-000000000001/cover.jpg')"
t "upload into a catalog meal's folder refused" A deny "insert into storage.objects(bucket_id,name) values ('meal-images','11111111-0000-0000-0000-000000000001/cover.jpg')"
t "upload into someone else's post folder refused" A deny "insert into storage.objects(bucket_id,name) values ('post-images','$B/x.jpg')"
t "upload to meal-audio refused" A deny "insert into storage.objects(bucket_id,name) values ('meal-audio','11111111-0000-0000-0000-000000000001/1.mp3')"
t "user can't list others' post images" B =0 "select count(*) from storage.objects where bucket_id='post-images'"
echo "### Admin approval, reward, push"
t "A registers push token" A ok "select register_push_token('ExponentPushToken[aaaa]','android')"
t "bad push token refused" A deny "select register_push_token('https://evil','android')"
t "admin approves A's recipe" ADM ok "update meals set status='approved' where id='33333333-0000-0000-0000-000000000001'"
t "A got 7 days of earned Pro" svc =t "select pro_reward_until between now()+interval '6 days 23 hours' and now()+interval '7 days 1 hour' from users where id='$A'"
t "approval push queued to Expo for A's token" svc =1 "select count(*) from net.calls where body::text like '%ExponentPushToken[aaaa]%'"
t "approval push uses android channel" svc =t "select (body->0->>'channelId') is not null or body::text like '%channelId%' from net.calls order by id desc limit 1"
t "approval sets published_at" svc =t "select published_at is not null from meals where id='33333333-0000-0000-0000-000000000001'"
t "S1: no audio after approval" svc =t "select procedure_audio is null from meals where id='33333333-0000-0000-0000-000000000001'"
t "A can no longer edit approved recipe (0 rows)" A =0 "with u as (update meals set name='changed' where id='33333333-0000-0000-0000-000000000001' returning 1) select count(*) from u"
t "A can no longer replace approved photo" A deny "insert into storage.objects(bucket_id,name) values ('meal-images','33333333-0000-0000-0000-000000000001/cover2.jpg')"
t "A cannot claim a 2nd recipe reward" ADM ok "insert into meals(id,name,status,poster_id) values ('33333333-0000-0000-0000-000000000002','Alice 2','approved','$A')"
t "  -> still exactly 1 recipe reward" svc =1 "select count(*) from pro_rewards where user_id='$A' and kind='recipe'"
t "A deletes approved recipe -> allowed" A =1 "with d as (delete from meals where id='33333333-0000-0000-0000-000000000001' returning 1) select count(*) from d"
t "  -> reward revoked, earned Pro ends" svc =t "select pro_reward_until <= now() + interval '1 minute' from users where id='$A'"
echo "### Food posts & photo reward"
t "post with external image refused" B deny "insert into food_posts(user_id,image_url) values ('$B','https://evil.example/x.jpg')"
t "post with non-klipy gif refused" B deny "insert into food_posts(user_id,gif_url) values ('$B','https://evil.example/x.gif')"
t "post with javascript: link refused" B deny "insert into food_posts(user_id,link_url) values ('$B','javascript:alert(1)')"
t "post as someone else refused" B deny "insert into food_posts(user_id,caption) values ('$A','hi')"
t "S5: photo post w/o uploaded file (allowed, no reward)" B ok "insert into food_posts(user_id,image_url) values ('$B','$BASE/post-images/$B/never-uploaded.jpg')"
t "S5:  -> no reward without the file" svc =t "select coalesce(pro_reward_until,now()) <= now()+interval '1 minute' from users where id='$B'"
t "S5: upload file then post it" B ok "insert into storage.objects(bucket_id,name) values ('post-images','$B/real.jpg')"
t "S5:  -> photo post with a real file" B ok "insert into food_posts(user_id,image_url) values ('$B','$BASE/post-images/$B/real.jpg')"
t "S5:  -> B got 7 days" svc =t "select pro_reward_until > now()+interval '6 days' from users where id='$B'"
t "B cannot un-hide via update (hidden_at not granted)" B deny "update food_posts set hidden_at=null where id=(select id from food_posts where image_url like '%real.jpg')"
t "B cannot report own post" B deny "select report_post((select id from food_posts where image_url like '%real.jpg'),'spam')"
t "A reports (1)" A ok "select report_post((select id from food_posts where image_url like '%real.jpg'),'spam')"
t "A reports again (dupe ignored)" A ok "select report_post((select id from food_posts where image_url like '%real.jpg'),'spam')"
t "  -> post still visible after 1 reporter" C =1 "select count(*) from get_food_posts() where image_url like '%real.jpg'"
t "C reports (2)" C ok "select report_post((select id from food_posts where image_url like '%real.jpg'),'spam')"
t "D reports (3) -> hidden" D ok "select report_post((select id from food_posts where image_url like '%real.jpg'),'spam')"
t "  -> hidden for others" PRO =0 "select count(*) from get_food_posts() where image_url like '%real.jpg'"
t "  -> poster still sees it, labelled hidden" B =t "select hidden from get_food_posts() where image_url like '%real.jpg'"
t "S4:  -> reward kept while hidden by reports" svc =t "select pro_reward_until > now()+interval '6 days' from users where id='$B'"
t "non-admin cannot remove posts" A deny "select remove_post((select id from food_posts where image_url like '%real.jpg'))"
t "non-admin get_reported_posts returns nothing" A =0 "select count(*) from get_reported_posts()"
t "admin sees reported post" ADM =1 "select count(*) from get_reported_posts()"
t "admin dismiss restores the post" ADM ok "select dismiss_post_reports((select id from food_posts where image_url like '%real.jpg'))"
t "  -> visible again" PRO =1 "select count(*) from get_food_posts() where image_url like '%real.jpg'"
t "S4:  -> reward still there after restore" svc =t "select pro_reward_until > now()+interval '6 days' from users where id='$B'"
t "S4: admin removes the reward post" ADM ok "select remove_post((select id from food_posts where image_url like '%real.jpg'))"
t "S4:  -> reward revoked by admin removal" svc =t "select pro_reward_until <= now()+interval '1 minute' from users where id='$B'"
t "block B" PRO ok "insert into user_blocks(blocker_id,blocked_id) values ('$PRO','$B')"
t "  -> B's posts gone for blocker" PRO =0 "select count(*) from get_food_posts() where image_url like '%real.jpg'"
t "  -> blocker cannot block on behalf of others" A deny "insert into user_blocks(blocker_id,blocked_id) values ('$C','$B')"
t "like as someone else refused" A deny "insert into food_post_likes(user_id,post_id) values ('$C',(select id from food_posts where image_url like '%real.jpg'))"
echo "### Saved meals limit"
t "free user saves 10 meals" C ok "insert into saved_meals(user_id,meal_id,meal_key,meal_data) select '$C', id, id::text, '{}' from meals where status='approved' order by name limit 10"
t "free user 11th save refused" C deny "insert into saved_meals(user_id,meal_id,meal_key,meal_data) select '$C', id, id::text, '{}' from meals where status='approved' order by name offset 10 limit 1"
t "pro user saves 15" PRO ok "insert into saved_meals(user_id,meal_id,meal_key,meal_data) select '$PRO', id, id::text, '{}' from meals where status='approved' order by name limit 15"
t "save_count tracked by trigger" svc =t "select save_count >= 2 from meals where name='Catalog meal 1'"
t "S2 (deferred, still open): saved meal_data is free-form JSON" D ok "insert into saved_meals(user_id,meal_id,meal_key,meal_data) values ('$D','11111111-0000-0000-0000-000000000002','x','{\"name\":\"FAKE\",\"image_url\":\"https://evil.example/p.png\"}')"
t "S2:  -> D makes saved meals public" svc ok "update users set show_saved_public=true where id='$D'"
t "S2:  -> B reads D's made-up meal_data (fix pending)" B =FAKE "select meal_data->>'name' from get_public_saved_meals('$D')"
t "pantry: cannot read others' pantry" B =0 "select count(*) from pantry_items where user_id='$A'"
echo "### Daily limits"
t "free: 10 searches allowed" A =t "select bool_and(allowed) from (select (count_daily_use('search','q'||g)).allowed from generate_series(1,10) g) x"
t "free: 11th search refused" A =f "select allowed from count_daily_use('search','q11')"
t "free: repeat of earlier search is free" A =t "select allowed from count_daily_use('search','q3')"
t "S3: non-JSON signature is never a refinement" A =f "select allowed from count_daily_use('search','q12',true)"
t "S3: app refine flag ignored when out of searches" A =f "select bool_or(allowed) from (select (count_daily_use('search','zz'||g,true)).allowed from generate_series(1,50) g) x"
t "free: 3 budget suggestions" A =t "select bool_and(allowed) from (select (count_daily_use('budget','b'||g)).allowed from generate_series(1,3) g) x"
t "free: 4th budget refused" A =f "select allowed from count_daily_use('budget','b4')"
t "free: 3 pantry ok, 4th refused" A =true,true,true,false "select string_agg(a::text, ',' order by g) from (select g, (count_daily_use('pantry','p'||g)).allowed a from generate_series(1,4) g) x"
t "free: 1 narration" A =t "select allowed from count_daily_use('narration','meal1')"
t "free: same meal narration again is free" A =t "select allowed from count_daily_use('narration','meal1')"
t "free: 2nd narrated meal refused" A =f "select allowed from count_daily_use('narration','meal2')"
t "pro: unlimited (uses_left null)" PRO = "select uses_left from count_daily_use('search','x')"
t "daily_uses_left for free budget = 0" A =0 "select daily_uses_left('budget')"
t "user cannot reset own usage row (0 rows)" A =0 "with u as (update daily_usage set count=0 where user_id='$A' returning 1) select count(*) from u"
t "unknown kind refused" A deny "select count_daily_use('admin','x')"
echo "### Push tokens"
t "B can steal A's token by re-registering it" B ok "select register_push_token('ExponentPushToken[aaaa]','android')"
t "  -> token moves to B (a phone changing hands)" svc =$B "select user_id from push_tokens where token='ExponentPushToken[aaaa]'"
t "unregister only own" A ok "select unregister_push_token('ExponentPushToken[aaaa]')"
t "  -> B's row still there" svc =1 "select count(*) from push_tokens where token='ExponentPushToken[aaaa]'"
t "users cannot read others' tokens" A =0 "select count(*) from push_tokens"
echo "### Admin-only reference data"
t "admin can edit ingredient" ADM =1 "with u as (update ingredients set estimated_price=5 returning 1) select count(*) from u"
t "user cannot write DA commodities" A deny "insert into da_commodities(commodity,section) values ('x','y')"
t "meal_sources hidden from users" A =0 "select count(*) from meal_sources"
t "price_alert_log hidden" A deny "select count(*) from price_alert_log"

echo "### S3 server-side refinements (user D, JSON signatures like the app)"
sig() { echo "[\"$1\",\"[]\"]"; }
t "S3: 'sin' counts" D =9 "select uses_left from count_daily_use('search','$(sig sin)')"
t "S3: 'sinigang' refines (free)" D =9 "select uses_left from count_daily_use('search','$(sig sinigang)')"
t "S3: back to 'sin' (free)" D =9 "select uses_left from count_daily_use('search','$(sig sin)')"
t "S3: 'p' counts" D =8 "select uses_left from count_daily_use('search','$(sig p)')"
t "S3: 'pork' counts (shorter < 3 letters)" D =7 "select uses_left from count_daily_use('search','$(sig pork)')"
t "S3: 'pancit' counts (no chaining)" D =6 "select uses_left from count_daily_use('search','$(sig pancit)')"
t "S3: same words, other filters free" D =6 "select uses_left from count_daily_use('search','[\"pancit\",\"[[\\\"pork\\\"]]\"]')"
t "S3: other words + other filters counts" D =5 "select uses_left from count_daily_use('search','[\"adobo\",\"[[\\\"pork\\\"]]\"]')"
t "S3:  -> 25 more refinements: cap hit, then the limit refuses" D =f "select bool_and(allowed) from (select (count_daily_use('search', '[\"adobo' || repeat('x', g) || '\",\"[[\\\"pork\\\"]]\"]')).allowed from generate_series(1,25) g) x"
t "S3:  -> refinements capped at 20" svc =20 "select refinements from daily_usage where user_id='$D' and kind='search'"
t "S3:  -> extra 5 counted (5 -> 0 left)" svc =10 "select count from daily_usage where user_id='$D' and kind='search'"
echo "### S6 recipe limit"
t "S6: C submits 8 recipes" C ok "insert into meals(name,status,poster_id) select 'C recipe '||g,'pending','$C' from generate_series(1,8) g"
t "S6: 9th refused" C deny "insert into meals(name,status,poster_id) values ('C recipe 9','pending','$C')"
t "S6: a rejected one frees a slot" ADM ok "update meals set status='rejected' where name='C recipe 1'"
t "S6:  -> 9th now allowed" C ok "insert into meals(name,status,poster_id) values ('C recipe 9','pending','$C')"
t "S6: admin not limited" ADM ok "insert into meals(name,status,poster_id) select 'Adm '||g,'approved','$ADM' from generate_series(1,10) g"
echo "### S1 existing audio on user recipes"
t "S1: poster may clear audio" C ok "update meals set procedure_audio=null where name='C recipe 2'"
t "S1: admin can still narrate catalog meals" ADM =1 "with u as (update meals set procedure_audio=array['x.mp3'] where name='Catalog meal 3' returning 1) select count(*) from u"

echo "### F6 moderation pushes"
t "F6: reset push log" svc ok "truncate net.calls; delete from push_tokens; insert into push_tokens(token,user_id,platform) values ('ExponentPushToken[bob]','$B','android')"
t "F6: B posts (no reward needed)" B ok "insert into food_posts(user_id,caption) values ('$B','F6 test post')"
t "F6: three reports hide it" svc ok "update food_posts set hidden_at=now(), hidden_reason='reports' where caption='F6 test post'"
t "F6:  -> push 'hidden for review' to B" svc =1 "select count(*) from net.calls where body::text like '%hidden for review%' and body::text like '%ExponentPushToken[bob]%'"
t "F6: admin removes it" ADM ok "select remove_post((select id from food_posts where caption='F6 test post'))"
t "F6:  -> push 'was removed'" svc =1 "select count(*) from net.calls where body::text like '%was removed%'"
t "F6: admin restores it" ADM ok "select dismiss_post_reports((select id from food_posts where caption='F6 test post'))"
t "F6:  -> push 'is back'" svc =1 "select count(*) from net.calls where body::text like '%is back%'"
t "F6:  -> tap data type post_moderation" svc =post_moderation "select body->0->'data'->>'type' from net.calls order by id desc limit 1"
t "F6: push off -> no push" svc ok "update users set push_enabled=false where id='$B'; update food_posts set hidden_at=now(), hidden_reason='reports' where caption='F6 test post'"
t "F6:  -> still 3 pushes" svc =3 "select count(*) from net.calls"
t "F6: poster sees hidden_reason" B =reports "select hidden_reason from get_food_posts() where caption='F6 test post'"
t "F6: others don't get the post" PRO =0 "select count(*) from get_food_posts() where caption='F6 test post'"
t "F6: guest still refused" anon deny "select count(*) from get_food_posts()"
echo "### F10 admin_list_users"
t "F10: guest refused" anon deny "select count(*) from admin_list_users()"
t "F10: regular user refused" A deny "select count(*) from admin_list_users()"
t "F10: admin lists everyone" ADM =6 "select count(*) from admin_list_users()"
t "F10: total_count on every row" ADM =6 "select max(total_count) from admin_list_users(p_limit => 2)"
t "F10: page size honoured" ADM =2 "select count(*) from admin_list_users(p_limit => 2)"
t "F10: search by email" ADM =1 "select count(*) from admin_list_users('pro@')"
t "F10: search by name, any case" ADM =1 "select count(*) from admin_list_users('caROL')"
t "F10: admin role shown" ADM =admin "select role from admin_list_users('adm@')"
t "F10: subscriber plan" ADM =subscriber "select plan from admin_list_users('pro@')"
t "F10: Pro filter = subscribers + earned" ADM =t "select bool_and(plan <> 'free') from admin_list_users(p_plan => 'pro')"
t "F10: Free filter" ADM =t "select bool_and(plan = 'free') from admin_list_users(p_plan => 'free')"
t "F10: bad plan refused" ADM deny "select count(*) from admin_list_users(p_plan => 'gold')"

echo "### F9 dead push tokens"
t "F9: three phones" svc ok "truncate net.calls, net._http_response; delete from push_deliveries; delete from push_receipts; delete from push_tokens; insert into push_tokens(token,user_id,platform) values ('ExponentPushToken[t1]','$A','android'),('ExponentPushToken[t2]','$B','android'),('ExponentPushToken[t3]','$C','ios')"
t "F9: send to all three" svc ok "select send_expo_push('[{\"to\":\"ExponentPushToken[t1]\",\"title\":\"x\"},{\"to\":\"ExponentPushToken[t2]\",\"title\":\"x\"},{\"to\":\"ExponentPushToken[t3]\",\"title\":\"x\"}]'::jsonb)"
t "F9:  -> delivery records tokens in order" svc ="ExponentPushToken[t1],ExponentPushToken[t2],ExponentPushToken[t3]" "select array_to_string(tokens, ',') from push_deliveries where kind='send'"
t "F9: Expo replies: ok, DeviceNotRegistered, ok" svc ok "insert into net._http_response(id,status_code,content) select request_id, 200, '{\"data\":[{\"status\":\"ok\",\"id\":\"r1\"},{\"status\":\"error\",\"message\":\"gone\",\"details\":{\"error\":\"DeviceNotRegistered\"}},{\"status\":\"ok\",\"id\":\"r3\"}]}' from push_deliveries where kind='send'"
t "F9: process" svc ="1 dead tokens removed; asked for 0 receipts" "select process_push_responses()"
t "F9:  -> t2 deleted, t1 t3 kept" svc ="ExponentPushToken[t1],ExponentPushToken[t3]" "select string_agg(token, ',' order by token) from push_tokens"
t "F9:  -> receipts r1 r3 waiting" svc =2 "select count(*) from push_receipts"
t "F9:  -> delivery cleared" svc =0 "select count(*) from push_deliveries"
t "F9: 15 minutes later, receipts asked" svc ="0 dead tokens removed; asked for 2 receipts" "update push_receipts set created_at = now() - interval '20 minutes'; select process_push_responses()"
t "F9:  -> getReceipts request with both ids" svc =t "select url like '%getReceipts' and body->'ids' @> '[\"r1\",\"r3\"]' from net.calls order by id desc limit 1"
t "F9: receipts reply: r3 DeviceNotRegistered" svc ok "insert into net._http_response(id,status_code,content) select request_id, 200, '{\"data\":{\"r1\":{\"status\":\"ok\"},\"r3\":{\"status\":\"error\",\"details\":{\"error\":\"DeviceNotRegistered\"}}}}' from push_deliveries where kind='receipts'"
t "F9: process again" svc ="1 dead tokens removed; asked for 0 receipts" "select process_push_responses()"
t "F9:  -> only t1 left" svc ="ExponentPushToken[t1]" "select string_agg(token, ',') from push_tokens"
t "F9:  -> receipts done" svc =0 "select count(*) from push_receipts"
t "F9: a failed request (500) is just dropped" svc ="0 dead tokens removed; asked for 0 receipts" "select send_expo_push('[{\"to\":\"ExponentPushToken[t1]\"}]'::jsonb); insert into net._http_response(id,status_code,content) select request_id, 500, 'oops' from push_deliveries; select process_push_responses()"
t "F9:  -> t1 kept" svc =1 "select count(*) from push_tokens"
t "F9: scheduled every 30 min" svc ="*/30 * * * *" "select schedule from cron.job where jobname='push-token-cleanup'"
t "F9: users can't read deliveries" A deny "select count(*) from push_deliveries"
t "F9: users can't read receipts" A deny "select count(*) from push_receipts"
t "F9: users can't run cleanup" A deny "select process_push_responses()"
echo "### BUG-2 rewards once per person (survive account deletion)"
E=eeeeeeee-0000-0000-0000-00000000000e; E2=eeeeeeee-0000-0000-0000-0000000000e2; F=ffffffff-0000-0000-0000-00000000000f
t "B2: E signs in with Apple" svc ok "insert into auth.users(id,email) values ('$E','e@test'); insert into auth.identities(user_id,provider,provider_id) values ('$E','apple','apple-sub-E')"
t "B2: E's recipe approved" ADM ok "insert into meals(id,name,status,poster_id) values ('33333333-0000-0000-0000-0000000000e1','Erin 1','approved','$E')"
t "B2:  -> E got 7 days" svc =t "select pro_reward_until > now()+interval '6 days' from users where id='$E'"
